1	import { redirect, notFound } from "next/navigation";
2	import { headers } from "next/headers";
3	
4	/**
5	 * Host gate: the admin portal is only reachable from the dedicated admin
6	 * hostname(s) in NXEON_ADMIN_HOSTS (comma-separated). On any other host — e.g.
7	 * the public nxeon.cloud — /admin 404s as if it doesn't exist. Empty/unset =
8	 * no host restriction (dev fallback). Returns true when access should be REFUSED.
9	 */
10	async function adminHostBlocked(): Promise<boolean> {
11	  const allow = (process.env.NXEON_ADMIN_HOSTS ?? "")
12	    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
13	  if (allow.length === 0) return false;
14	  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
15	  return !allow.includes(host);
16	}
17	import { realUser, impersonating } from "@/lib/auth";
18	import { isStaff, canAccessHref } from "@/lib/rbac";
19	import { db } from "@/lib/db";
20	import { getSetting, getSettingBool } from "@/lib/settings";
21	import { Shell, type NavSection } from "@/components/portal/Shell";
22	import { ADMIN_GROUPS } from "@/lib/admin-groups";
23	
24	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
25	function isPlainIp(s: string): boolean {
26	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
27	}
28	
29	/**
30	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
31	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
32	 * parseable entries or the requester IP can't be determined, so a bad value can
33	 * never lock every admin out — only an exact match is ever enforced.
34	 * Returns true when access should be REFUSED.
35	 */
36	async function adminIpBlocked(): Promise<boolean> {
37	  const raw = await getSetting("allowed_admin_ips", "");
38	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
39	  if (entries.length === 0) return false; // no restriction configured
40	  const valid = entries.filter(isPlainIp);
41	  if (valid.length === 0) {
42	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
43	    return false; // malformed -> fail open
44	  }
45	  const hdrs = await headers();
46	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
47	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
48	  // client-supplied leftmost entry.
49	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
50	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
51	  if (!ip) {
52	    console.warn("[admin-ip] could not determine requester IP; failing open");
53	    return false;
54	  }
55	  return !valid.includes(ip);
56	}
57	
58	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
59	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
60	  if (await adminHostBlocked()) notFound();
61	
62	  const user = await realUser();
63	  if (!user) redirect("/login");
64	  if (!isStaff(user.role)) redirect("/dashboard");
65	  const imp = await impersonating();
66	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
67	
68	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
69	  if (await adminIpBlocked()) {
70	    return (
71	      <main
72	        style={{
73	          minHeight: "100vh",
74	          display: "flex",
75	          flexDirection: "column",
76	          alignItems: "center",
77	          justifyContent: "center",
78	          gap: "0.75rem",
79	          padding: "2rem",
80	          textAlign: "center",
81	        }}
82	      >
83	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
84	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
85	          The admin console isn&apos;t available from your current network.
86	        </p>
87	      </main>
88	    );
89	  }
90	
91	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
92	  // using admin tools. Redirect (don't hard-fail) to their security settings so
93	  // they can enroll, then come back.
94	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
95	    redirect("/dashboard/settings?require2fa=1");
96	  }
97	
98	  // Filter each group's members to what this role can access; drop groups that
99	  // end up empty. The group header will link to its first *accessible* member.
100	  const visibleGroups = ADMIN_GROUPS.map((g) => ({
101	    group: g,
102	    items: g.items.filter((item) => canAccessHref(user.role, item.href)),
103	  })).filter((g) => g.items.length > 0);
104	
105	  const notifications = await db.notification.findMany({
106	    where: { userId: user.id },
107	    orderBy: { createdAt: "desc" },
108	    take: 15,
109	  });
110	
111	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
112	  // missing model/table can never break the admin layout.
113	  const soft = (p: Promise<number>) => p.catch(() => 0);
114	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
115	    // Live chat: conversations flagged unread for agents (same "needs a reply"
116	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
117	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
118	    // Support desk: tickets awaiting a staff reply (open + customer replies),
119	    // matching the "Awaiting staff" stat on /admin/support.
120	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
121	    // Abuse queue: alerts still OPEN.
122	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
123	    // Feedback: new (untriaged) reports.
124	    soft(db.feedback.count({ where: { status: "NEW" } })),
125	    // Improvements board: proposals awaiting the owner's approve/decline.
126	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
127	  ]);
128	
129	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
130	  const badges: Record<string, number> = {
131	    "/admin/chat": chatUnread,
132	    "/admin/support": ticketsAwaiting,
133	    "/admin/abuse": abuseOpen,
134	    "/admin/feedback": feedbackNew,
135	    "/admin/improvements": improvementsProposed,
136	  };
137	  // Build the sidebar nav as one visible SECTION per group: the group label is
138	  // the section header, and its accessible members are listed as flat links
139	  // beneath it (the same shape the customer portal uses). All sections render at
140	  // once so the full nav fills the vertical space instead of collapsing to lone
141	  // group rows. Each item keeps its own per-route attention badge.
142	  const nav: NavSection[] = visibleGroups.map(({ group, items }) => ({
143	    label: group.label,
144	    items: items.map((item) => ({
145	      label: item.label,
146	      href: item.href,
147	      badge: badges[item.href] > 0 ? badges[item.href] : undefined,
148	    })),
149	  }));
150	
151	  return (
152	    <Shell
153	      nav={nav}
154	      tag="ops"
155	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
156	      notifications={notifications.map((n) => ({
157	        id: n.id,
158	        title: n.title,
159	        body: n.body,
160	        href: n.href,
161	        readAt: n.readAt ? n.readAt.toISOString() : null,
162	        createdAt: n.createdAt.toISOString(),
163	      }))}
164	    >
165	      {children}
166	    </Shell>
167	  );
168	}
