147	export function Shell({
148	  nav,
149	  user,
150	  notifications,
151	  impersonation,
152	  tag,
153	  children,
154	}: {
155	  nav: NavSection[];
156	  user: { name: string; email: string; role: string; balanceCents: number };
157	  notifications: ShellNotification[];
158	  impersonation?: { adminName: string; targetEmail: string } | null;
159	  tag?: string;
160	  children: React.ReactNode;
161	}) {
162	  const pathname = usePathname();
163	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
164	  // main so they fill the entire content area under the header with no gap.
165	  const fullBleed = pathname === "/dashboard/mail" || pathname === "/dashboard/calendar";
166	  const [notifOpen, setNotifOpen] = useState(false);
167	  const [sidebarOpen, setSidebarOpen] = useState(false);
168	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
169	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
170	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
171	  const [collapsed, setCollapsed] = useState(false);
172	  const [, startTransition] = useTransition();
173	
174	  useEffect(() => {
175	    try {
176	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
177	    } catch {}
178	  }, []);
179	  function toggleCollapsed() {
180	    setCollapsed((c) => {
181	      const next = !c;
182	      try {
183	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
184	      } catch {}
185	      return next;
186	    });
187	  }
188	  const unread = notifications.filter((n) => !n.readAt).length;
189	
190	  // Flatten for the command palette: when a nav item has children, expose the
191	  // children (the real destinations) instead of the group header; flat items
192	  // (customer portal) pass through unchanged.
193	  const flatNav = nav.flatMap((s) =>
194	    s.items.flatMap((i) =>
195	      i.children && i.children.length > 0
196	        ? i.children.map((c) => ({ label: c.label, href: c.href, section: s.label }))
197	        : [{ label: i.label, href: i.href, section: s.label }]
198	    )
199	  );
200	
201	  // Longest-prefix match across every group's children, mirroring
202	  // groupForPath() in lib/admin-groups.ts. The single winning href both
203	  // highlights its sub-link and expands its parent group. Bare "/admin" only
204	  // matches exactly so it never swallows deeper routes.
205	  let activeChildHref: string | null = null;
206	  {
207	    let bestLen = -1;
208	    for (const section of nav) {
209	      for (const item of section.items) {
210	        for (const c of item.children ?? []) {
211	          const matches =
212	            c.href === pathname ||
213	            (c.href !== "/admin" && pathname.startsWith(c.href + "/"));
214	          if (matches && c.href.length > bestLen) {
215	            activeChildHref = c.href;
216	            bestLen = c.href.length;
217	          }
218	        }
219	      }
220	    }
221	  }
222	
223	  return (
224	    // The terminal dock lives at the shell level so a shell session survives
225	    // in-portal navigation: App Router keeps Shell mounted across page changes,
226	    // so the dock (and its live sockets) is never unmounted. The provider is
227	    // inert until a page calls useTerminalDock().openSession(...).
228	    <TerminalDockProvider>
229	    <div className="flex min-h-screen">
230	      <CommandPalette nav={flatNav} />
231	      <FeedbackWidget />
232	      <VisitTracker kind="portal" />
233	
234	      {/* Sidebar */}
235	      <aside
236	        className={`fixed inset-y-0 left-0 z-40 flex w-60 flex-col border-r border-white/[0.06] bg-navy-900/80 backdrop-blur-xl transition-all lg:static lg:translate-x-0 ${
237	          collapsed ? "lg:w-[4.75rem]" : "lg:w-60"
238	        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
239	      >
240	        <div className={`flex h-16 items-center px-4 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
241	          <Logo tag={tag} collapsed={collapsed} />
242	        </div>
243	        <nav className={`flex-1 space-y-5 overflow-y-auto px-3 pb-6 pt-2 ${collapsed ? "lg:px-2" : ""}`}>
244	          {nav.map((section, si) => (
245	            <div key={si}>
246	              {section.label && (
247	                <p className={`section-label mb-2 px-3 ${collapsed ? "lg:hidden" : ""}`}>{section.label}</p>
248	              )}
249	              <div className="space-y-0.5">
250	                {section.items.map((item) => {
251	                  // Expandable group (admin ops portal): render a header row plus
252	                  // indented sub-links when this group owns the active route.
253	                  if (item.children && item.children.length > 0) {
254	                    const open = item.children.some((c) => c.href === activeChildHref);
255	                    return (
256	                      <div key={item.href}>
257	                        <Link
258	                          href={item.href}
259	                          onClick={() => setSidebarOpen(false)}
260	                          className={`nav-item ${open ? "text-white" : ""}`}
261	                        >
262	                          {item.icon && <Icon name={item.icon} />}
263	                          <span className="flex-1 truncate">{item.label}</span>
264	                          {/* Collapsed: rolled-up group total. Expanded: the count
265	                              moves onto the individual sub-links below. */}
266	                          {!open && typeof item.badge === "number" && item.badge > 0 && (
267	                            <span className="flex h-[18px] min-w-[18px] items-center justify-center rounded-full bg-brand-500 px-1.5 text-[10px] font-semibold text-white">
268	                              {item.badge > 99 ? "99+" : item.badge}
269	                            </span>
270	                          )}
271	                          <svg
272	                            width="13"
273	                            height="13"
274	                            viewBox="0 0 24 24"
275	                            fill="none"
276	                            stroke="currentColor"
277	                            strokeWidth="2.2"
278	                            strokeLinecap="round"
279	                            strokeLinejoin="round"
280	                            className={`shrink-0 text-slate-500 transition-transform ${open ? "rotate-90" : ""}`}
281	                          >
282	                            <path d="M9 6l6 6-6 6" />
283	                          </svg>
284	                        </Link>
285	                        {open && (
286	                          <div className="mb-1 ml-[1.6rem] mt-0.5 space-y-0.5 border-l border-white/[0.08] pl-2">
287	                            {item.children.map((c) => {
288	                              const cActive = c.href === activeChildHref;
289	                              return (
290	                                <Link
291	                                  key={c.href}
292	                                  href={c.href}
293	                                  onClick={() => setSidebarOpen(false)}
294	                                  className={`flex items-center gap-2 rounded-lg py-1.5 pl-3 pr-2.5 text-[13px] font-medium transition-colors ${
295	                                    cActive
296	                                      ? "nav-item-active"
297	                                      : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
298	                                  }`}
299	                                >
300	                                  <span className="flex-1 truncate">{c.label}</span>
301	                                  {typeof c.badge === "number" && c.badge > 0 && (
302	                                    <span
303	                                      className={`flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold ${
304	                                        cActive ? "bg-white/25 text-white" : "bg-brand-500 text-white"
305	                                      }`}
306	                                    >
307	                                      {c.badge > 99 ? "99+" : c.badge}
308	                                    </span>
309	                                  )}
310	                                </Link>
311	                              );
312	                            })}
313	                          </div>
314	                        )}
315	                      </div>
316	                    );
317	                  }
318	
319	                  // Flat link (customer portal) — unchanged behavior.
320	                  const active =
321	                    item.href === pathname ||
322	                    (item.href !== "/dashboard" && item.href !== "/admin" && pathname.startsWith(item.href));
323	                  const hasBadge = typeof item.badge === "number" && item.badge > 0;
324	                  return (
325	                    <Link
326	                      key={item.href}
327	                      href={item.href}
328	                      onClick={() => setSidebarOpen(false)}
329	                      title={collapsed ? item.label : undefined}
330	                      className={`nav-item relative ${active ? "nav-item-active" : ""} ${
331	                        collapsed ? "lg:justify-center lg:px-2.5" : ""
