const keys=[...map.matchAll(/^  ([a-z]+):/gm)].map(m=>m[1]);
const nav=fs.readFileSync("lib/admin-groups.ts","utf8");
const used=[...nav.matchAll(/icon: "([a-z]+)"/g)].map(m=>m[1]);
console.log("icons map keys:", keys.join(", "));
console.log("admin icons used:", [...new Set(used)].join(", "));
console.log("MISSING:", [...new Set(used)].filter(u=>!keys.includes(u)));
const cust=fs.readFileSync("app/dashboard/layout.tsx","utf8");
const cu=[...cust.matchAll(/icon: "([a-z]+)"/g)].map(m=>m[1]);
console.log("customer icons missing:", [...new Set(cu)].filter(u=>!keys.includes(u)));
